//! The runtime ID (D-930) and the archive's data symbol that carries it,
//! both generated by `build.rs` into `$OUT_DIR/runtime_id.rs`. This is the
//! only place that includes the generated file, so the symbol
//! `cheby_rt_id$<hex>` is defined once. Code generation reads the
//! constants as `abi::RUNTIME_ID`, `abi::RUNTIME_ID_HEX` and
//! `abi::sym::RUNTIME_ID_SYMBOL`.

include!(concat!(env!("OUT_DIR"), "/runtime_id.rs"));
